import socket
import ssl
from tls_client import wrap_client_socket


def fetch_greeting(host: str, port: int, cafile: str, server_hostname: str = None) -> bytes:
    """Open a TLS connection to host:port, verify server cert against cafile and hostname,
    and return the server's greeting bytes up to and including the first newline or until closed,
    at most 4096 bytes."""
    if server_hostname is None:
        server_hostname = host

    # Create a plain TCP socket and connect
    sock = socket.create_connection((host, port))
    try:
        # Wrap the socket in TLS with verification of cert and hostname
        tls_sock = wrap_client_socket(sock, server_hostname=server_hostname, cafile=cafile)
        try:
            # Read up to 4096 bytes or until newline
            data = bytearray()
            while len(data) < 4096:
                chunk = tls_sock.recv(4096 - len(data))
                if not chunk:
                    # Connection closed by server
                    break
                data.extend(chunk)
                if b"\n" in chunk:
                    # Stop after the first newline
                    break
            # Return bytes up to and including the first newline if present
            newline_index = data.find(b"\n")
            if newline_index >= 0:
                return bytes(data[:newline_index + 1])
            else:
                return bytes(data)
        finally:
            tls_sock.close()
    except Exception:
        sock.close()
        raise
